import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.CPvOxTBX.js";const p=JSON.parse('{"title":"键盘快捷键","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/keyboard-shortcuts.md","filePath":"zh/guide/keyboard-shortcuts.md","lastUpdated":1793628426000}'),r={name:"zh/guide/keyboard-shortcuts.md"};function c(l,t,h,n,i,s){return e(),o("div",null,t[0]||(t[0]=[a(`<h1 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to &quot;键盘快捷键&quot;">​</a></h1><p>词悦的快捷键沿用 <a href="https://github.com/xiaoyifang/goldendict-ng" target="_blank" rel="noreferrer">GoldenDict-ng</a> 与 EBWin 的习惯：在其它词典里已经用顺手的键，在这里做同样的事。</p><p>其中大部分<strong>仅限桌面端</strong>，因为它们需要实体键盘。在 Android 上基本用不上，除非外接了蓝牙键盘。</p><h2 id="两个层级" tabindex="-1">两个层级 <a class="header-anchor" href="#两个层级" aria-label="Permalink to &quot;两个层级&quot;">​</a></h2><p>与词典有关的快捷键分两层：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ctrl+\`  /  Ctrl+1…9      分组：查词时用哪些词典</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └── Alt+0…9       词典：看哪一部词典的结果</span></span>
<span class="line"><span>                            Alt+0 = AI 解释，Alt+1…9 = 第 1…9 部词典</span></span></code></pre></div><h2 id="查词" tabindex="-1">查词 <a class="header-anchor" href="#查词" aria-label="Permalink to &quot;查词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>F</code></td><td>把焦点移进搜索框</td></tr><tr><td><code>Esc</code></td><td>把焦点移进搜索框，<strong>并选中框里的文字</strong>，直接输入即可覆盖；再按一次回到词条</td></tr><tr><td>选中文字后按 <code>Enter</code></td><td>查选中的文字（见下）</td></tr></tbody></table><p>宽窗口里有两个搜索框：左栏的那个，和词条标题栏里的那个。<code>Ctrl</code>+<code>F</code> 和 <code>Esc</code> 会落到你最后用过的那个，跟着你在窗口里走动，而不是每次都落在左边那个。</p><h3 id="查选中的文字" tabindex="-1">查选中的文字 <a class="header-anchor" href="#查选中的文字" aria-label="Permalink to &quot;查选中的文字&quot;">​</a></h3><p>在释义里选中一个词或一个短语，按 <code>Enter</code> 即可查词。这是 EBWin 的做法，在桌面端这也是唯一的选词查词途径——释义页的右键菜单是 Chromium 自带的，只提供复制和检查元素。</p><p>选中比双击好用，因为双击在那些不用空格分词的语言里永远只能选中词的一部分：</p><table tabindex="0"><thead><tr><th>语言</th><th>双击选到</th><th>选中整个短语得到</th></tr></thead><tbody><tr><td>德语</td><td><code>Bundesbankdirektor</code> 里的 <code>Bundesbank</code></td><td><code>Bundesbankdirektor</code></td></tr><tr><td>日语</td><td><code>日本語词典</code> 里的 <code>日本</code></td><td><code>日本語词典</code></td></tr><tr><td>中文</td><td><code>现代汉语词典</code> 里的 <code>现代</code></td><td><code>现代汉语词典</code></td></tr></tbody></table><p>在 Android 上，长按菜单里也有同样的查词项，旁边是复制和朗读；用鼠标右键点一个词也会选中它，菜单里的「查询」查的就是这个词。</p><h2 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to &quot;标签&quot;">​</a></h2><p>词悦里有三种标签，很容易混。</p><h3 id="单词标签" tabindex="-1">单词标签 <a class="header-anchor" href="#单词标签" aria-label="Permalink to &quot;单词标签&quot;">​</a></h3><p>顶部那排类似浏览器的标签，每个标签放一个词。</p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>T</code></td><td>新建标签</td></tr><tr><td><code>Ctrl</code>+<code>W</code></td><td>关闭当前标签</td></tr><tr><td><code>Ctrl</code>+<code>Tab</code></td><td>下一个标签</td></tr><tr><td><code>Ctrl</code>+<code>Shift</code>+<code>Tab</code></td><td>上一个标签</td></tr><tr><td><code>Ctrl</code>+<code>PgDn</code> / <code>Ctrl</code>+<code>PgUp</code></td><td>下一个 / 上一个标签</td></tr></tbody></table><p>在移动端的全屏单词列表里，<code>←</code> / <code>→</code> 翻到上一个 / 下一个词。</p><h3 id="词典分组" tabindex="-1">词典分组 <a class="header-anchor" href="#词典分组" aria-label="Permalink to &quot;词典分组&quot;">​</a></h3><p>分组决定查词时用哪些词典。分组按创建顺序列在窗口顶部的菜单里，快捷键也按这个顺序编号。</p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code> + 反引号</td><td>切到第一个分组，即默认分组</td></tr><tr><td><code>Ctrl</code>+<code>1</code> … <code>Ctrl</code>+<code>9</code></td><td>切到第二个到第十个分组</td></tr></tbody></table><p>超出分组数量的数字不做任何事。切换之后，当前屏幕上的词会用新分组的词典重新查一遍。</p><h3 id="词典标签" tabindex="-1">词典标签 <a class="header-anchor" href="#词典标签" aria-label="Permalink to &quot;词典标签&quot;">​</a></h3><p>词典切换样式为<strong>标签式</strong>时，每部词典在释义区里有一个标签，数字键用来挑其中之一。</p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Alt</code>+<code>1</code> … <code>Alt</code>+<code>9</code></td><td>显示第 1 到第 9 部词典</td></tr><tr><td><code>Alt</code>+<code>0</code></td><td>显示 AI 解释（需要开启该功能）</td></tr></tbody></table><p><strong>展开式</strong>下没有这些标签，这组键完全不做任何事。</p><h2 id="朗读" tabindex="-1">朗读 <a class="header-anchor" href="#朗读" aria-label="Permalink to &quot;朗读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>R</code></td><td>朗读当前词；正在朗读时再按一次则停止</td></tr><tr><td><code>Ctrl</code>+<code>Shift</code>+<code>S</code></td><td>停止播放</td></tr><tr><td><code>Ctrl</code>+<code>↑</code> / <code>Ctrl</code>+<code>↓</code></td><td>在历史记录里选上一个 / 下一个词</td></tr></tbody></table><h2 id="缩放释义" tabindex="-1">缩放释义 <a class="header-anchor" href="#缩放释义" aria-label="Permalink to &quot;缩放释义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><code>Ctrl</code>+= / <code>Ctrl</code>++</td><td>放大释义</td></tr><tr><td><code>Ctrl</code>+-</td><td>缩小释义</td></tr><tr><td><code>Ctrl</code>+<code>0</code></td><td>恢复默认大小</td></tr></tbody></table><p>只有释义会被缩放，窗口的其它部分保持原样。缩放级别会被记住，重启后依然有效；<a href="/Ciyue/zh/guide/appearance.html">词典外观</a> 里也有对应的滑块。</p><p>大多数键盘上 <code>Ctrl</code>+= 和 <code>Ctrl</code>++ 是同一个键，两者都绑定了，按哪个都行。</p><h2 id="其它页面" tabindex="-1">其它页面 <a class="header-anchor" href="#其它页面" aria-label="Permalink to &quot;其它页面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th><th>位置</th></tr></thead><tbody><tr><td><code>Ctrl</code>+<code>Enter</code></td><td>翻译文本</td><td>翻译</td></tr><tr><td><code>Ctrl</code>+<code>Enter</code></td><td>检查文本</td><td>写作检查</td></tr><tr><td><code>Space</code></td><td>显示答案</td><td>抽认卡</td></tr><tr><td><code>1</code> … <code>4</code></td><td>评价卡片</td><td>抽认卡</td></tr></tbody></table><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>分组与词典标签的快捷键只在释义页在前台时生效。</li><li>如果窗口管理器占用了 <code>Alt</code>+数字，就没法用这组键切换词典标签。</li><li><code>Ctrl</code>+<code>PgUp</code> 与 <code>Ctrl</code>+<code>PgDn</code> 切的是单词标签；单独按这两个键（不带 <code>Ctrl</code>）在展开式下用来翻页。</li><li>桌面布局下，方向键用于在控件之间移动焦点，<code>Enter</code> 或 <code>Space</code> 激活当前聚焦的控件。</li></ul>`,38)]))}const u=d(r,[["render",c]]);export{p as __pageData,u as default};
